/* Кинотека — vanilla JavaScript, без сборщика и внешних JS-зависимостей. */
'use strict';
const API = 'https://kinopoiskapiunofficial.tech';
const $ = (s,root=document) => root.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text = (s,f='Не указано') => (s===undefined||s===null||s===''?f:String(s));
const join = (items,k) => (items||[]).map(x=>x[k]).filter(Boolean).join(', ');
const idOf = x => Number(x?.kinopoiskId || x?.filmId || x?.id || 0);
const filmTitle = x => x?.nameRu || x?.nameOriginal || x?.nameEn || 'Без названия';
const img = (url,alt='',cls='',attrs='') => url && /^https?:\/\//i.test(url) ? `<img class="${cls}" src="${esc(url)}" alt="${esc(alt)}" loading="lazy" referrerpolicy="no-referrer" ${attrs}>` : `<div class="poster-empty" aria-label="Нет изображения">▶</div>`;
const keyName = 'kinoteka.apiKey';
const savedKey = localStorage.getItem(keyName);
let apiKey = savedKey || sessionStorage.getItem(keyName) || '';
const storeName = 'kinoteka.lists.v1';
const defaultLists = {watchlist:[],watched:[],favorites:[]};
function getLists(){try{const o=JSON.parse(localStorage.getItem(storeName)||'{}');return Object.fromEntries(Object.entries(defaultLists).map(([k])=>[k,Array.isArray(o[k])?o[k]:[]]));}catch{return structuredClone(defaultLists)}}
let lists = getLists();
const cache = new Map();
const knownFilms = new Map();
let activeGallery=[];let currentImage=0;let invalidLinkTimer;let hdRequestToken=0;
const state = {page:1,keyword:'',type:'ALL',genre:'',country:'',year:'',rating:'',order:'RATING',collection:'TOP_POPULAR_MOVIES',list:'watchlist',detailTab:'overview',film:null,person:null,filters:null};
const listLabels={watchlist:'Хочу посмотреть',watched:'Просмотрено',favorites:'Любимые'};
let toastTimer;
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),3700)}
function writeLists(){localStorage.setItem(storeName,JSON.stringify(lists));}
function inList(id,list){return lists[list].some(x=>idOf(x)===Number(id))}
function compactFilm(x){return {kinopoiskId:idOf(x),nameRu:x.nameRu,nameEn:x.nameEn,nameOriginal:x.nameOriginal,year:x.year,posterUrl:x.posterUrl,posterUrlPreview:x.posterUrlPreview,ratingKinopoisk:x.ratingKinopoisk ?? x.rating,genres:x.genres,type:x.type};}
function toggleList(film,list){const id=idOf(film);if(!id)return;lists[list]=inList(id,list)?lists[list].filter(x=>idOf(x)!==id):[compactFilm(film),...lists[list]];writeLists();toast((inList(id,list)?'Добавлено: ':'Удалено: ')+listLabels[list]);}
function statusError(err){let s=err?.message||'Ошибка загрузки';return `<div class="error-note"><strong>Не удалось загрузить данные.</strong><p>${esc(s)}</p><button class="btn outline small" data-action="retry">Повторить</button></div>`}
async function request(path,params={},options={}){
  if(!apiKey)throw Error('Для загрузки каталога подключите свой API-ключ в настройках.');
  const url=new URL(path,API);
  Object.entries(params).forEach(([k,v])=>{if(v!==undefined && v!==null && v!=='')url.searchParams.set(k,String(v))});
  const cacheKey=url.toString();
  if(!options.noCache && cache.has(cacheKey))return cache.get(cacheKey);
  const res=await fetch(url,{headers:{'X-API-KEY':apiKey,'Accept':'application/json'},signal:options.signal});
  if(!res.ok){const msg={400:'Некорректный запрос',401:'Неверный или отсутствующий API-ключ',402:'Исчерпана квота API-ключа',403:'Доступ к API запрещён',404:'Данные не найдены',429:'Слишком много запросов; попробуйте немного позже'}[res.status]||`Ошибка API (${res.status})`;throw Error(msg)}
  const data=await res.json();if(!options.noCache)cache.set(cacheKey,data);return data;
}
function loading(){return '<div class="loading"><div class="spinner"></div>Загружаем киноистории…</div>'}
function noKey(){return `<div class="empty"><div class="em-icon">🔑</div><h2>Начнём с вашего API-ключа</h2><p>У каждого зрителя свой ключ — ваши запросы выполняются непосредственно из браузера.</p><button class="btn primary" data-action="settings">Подключить API ↗</button></div>`}
function rating(x){let r=x?.ratingKinopoisk ?? x?.rating;if(typeof r==='string')r=r.replace(/%/g,'');return r && !isNaN(Number(r)) ? `<span class="rating">★ ${esc(r)}</span>` : ''}
function card(x){const id=idOf(x);if(id)knownFilms.set(id,compactFilm(x));const poster=x.posterUrlPreview||x.posterUrl;return `<article class="movie-card"><a href="#film/${id}" class="poster" aria-label="Подробнее: ${esc(filmTitle(x))}">${img(poster,filmTitle(x))}${rating(x)}</a><button class="heart ${inList(id,'watchlist')?'on':''}" aria-label="${inList(id,'watchlist')?'Убрать из списка':'Хочу посмотреть'}" data-action="watch" data-id="${id}" title="Хочу посмотреть">${inList(id,'watchlist')?'♥':'♡'}</button><a href="#film/${id}" class="movie-title">${esc(filmTitle(x))}</a><div class="movie-meta">${esc(x.year||'Год не указан')} ${x.genres?.length?'· '+esc(x.genres.slice(0,2).map(g=>g.genre).join(', ')):''}</div></article>`}
function cards(items){return items?.length?`<div class="film-grid">${items.map(card).join('')}</div>`:`<div class="empty"><div class="em-icon">◎</div><h2>Пока ничего не найдено</h2><p>Попробуйте изменить фильтры или другой поисковый запрос.</p></div>`}
function sectionHeading(label,heading,link){return `<div class="section-head"><div><span class="eyebrow">${label}</span><h2>${heading}</h2></div>${link?`<a class="section-link" href="${link}">Смотреть все ↗</a>`:''}</div>`}
function root(html){$('#main').innerHTML=`<div class="wrap">${html}</div>`;markNav()}
function markNav(){const route=location.hash.slice(1).split('/')[0]||'home';document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===route))}
async function home(){root(`<section class="intro"><div class="orbit"></div><div class="hero-cinema" aria-hidden="true"><span class="reel-disc"><i></i><i></i><i></i><i></i><i></i><b></b></span><span class="reel-tail"></span></div><div class="intro-content"><span class="eyebrow">ВАШ ПЕРСОНАЛЬНЫЙ МИР КИНО</span><h1>У каждой истории<br>есть <em>свой зритель.</em></h1><p>Исследуйте фильмы и сериалы, находите новых любимых героев и собирайте истории, которые хочется посмотреть.</p><div class="intro-actions"><a href="#catalog" class="btn primary">Исследовать каталог ↗</a><a href="#lists" class="btn outline">♡ Мой список</a></div></div></section><section class="section" id="home-popular">${sectionHeading('ВДОХНОВЕНИЕ НА СЕГОДНЯ','Топ-100 популярных фильмов','#collection/TOP_POPULAR_MOVIES')}<div id="homeFilms">${apiKey?loading():noKey()}</div></section><section class="section" id="home-top">${sectionHeading('ВЫБОР ЗРИТЕЛЕЙ','Топ-10 Кинопоиска','#collection/TOP_250_MOVIES')}<div id="topFilms">${apiKey?loading():noKey()}</div></section><section class="section" id="home-genres">${sectionHeading('ПО НАСТРОЕНИЮ','Подборки по жанрам','#catalog')}<div class="genre-links" id="genreLinks">${apiKey?loading():noKey()}</div><div id="genrePreview"></div></section><section class="section">${sectionHeading('СОХРАНЕНО ДЛЯ ВАС','Хочу посмотреть','#lists')}<div>${lists.watchlist.length?cards(lists.watchlist.slice(0,5)):`<div class="empty"><div class="em-icon">♡</div><h2>Здесь начнётся ваш список</h2><p>Нажимайте на сердечко возле фильма, и он появится здесь.</p><a href="#catalog" class="btn outline">Найти фильм ↗</a></div>`}</div></section>`);
  if(!apiKey)return;
  const sections=[['TOP_POPULAR_MOVIES','#homeFilms'],['TOP_250_MOVIES','#topFilms']];
  await Promise.all(sections.map(async([type,selector])=>{try{const data=await request('/api/v2.2/films/collections',{type,page:1});if($(selector))$(selector).innerHTML=cards((data.items||[]).slice(0,selector==='#topFilms'?10:10))}catch(e){if($(selector))$(selector).innerHTML=statusError(e)}}));
  try{
    const filters=state.filters||await request('/api/v2.2/films/filters');state.filters=filters;
    const genres=(filters.genres||[]).filter(x=>['драма','комедия','фантастика','триллер','ужасы','аниме','детектив','мелодрама','приключения','боевик'].includes(String(x.genre).toLowerCase()));
    if($('#genreLinks'))$('#genreLinks').innerHTML=genres.map(g=>`<button class="genre-tile" data-action="genreJump" data-genre="${g.id}">${esc(g.genre)} <span>↗</span></button>`).join('');
    if(genres[0]&&$('#genrePreview')){const data=await request('/api/v2.2/films',{genres:genres[0].id,order:'NUM_VOTE',page:1});if($('#genrePreview'))$('#genrePreview').innerHTML=`<h3>Популярное в жанре «${esc(genres[0].genre)}»</h3>`+cards((data.items||[]).slice(0,5))}
  }catch(e){if($('#genreLinks'))$('#genreLinks').innerHTML='<p class="muted">Подборки по жанрам сейчас недоступны.</p>'}
}
async function collectionPage(type,page=1){
 const isPopular=type==='TOP_POPULAR_MOVIES';const title=isPopular?'Топ-100 популярных фильмов':'Лучшие фильмы Кинопоиска';
 root(`<section class="page-heading"><span class="eyebrow">ПОДБОРКА КИНОПОИСКА</span><h1>${title}</h1><p>${isPopular?'Популярные фильмы по коллекции API.':'Рейтинг лучших фильмов. Первые десять образуют блок «Топ-10» на главной.'}</p></section><div id="collectionResults">${apiKey?loading():noKey()}</div><div class="more-wrap" id="collectionMore"></div>`);
 if(!apiKey)return;
 try{const d=await request('/api/v2.2/films/collections',{type,page});if(location.hash!=='#collection/'+type)return;
 $('#collectionResults').innerHTML=cards(d.items||[]);
 const pages=d.totalPages||Math.ceil((d.total||0)/20);
 $('#collectionMore').innerHTML=`<div class="collection-pages">${page>1?`<button class="btn outline" data-action="collectionPage" data-type="${type}" data-page="${page-1}">← Назад</button>`:''}<span class="pill">Страница ${page}${pages?' из '+pages:''}</span>${page<pages?`<button class="btn primary" data-action="collectionPage" data-type="${type}" data-page="${page+1}">Далее →</button>`:''}</div>`;
 }catch(e){if($('#collectionResults'))$('#collectionResults').innerHTML=statusError(e)}
}
function filterOptions(items,key){return (items||[]).map(x=>`<option value="${x.id}" ${String(x.id)===String(state[key])?'selected':''}>${esc(x.genre||x.country)}</option>`).join('')}
function catalogLayout(){return `<section class="page-heading"><span class="eyebrow">ОТКРОЙТЕ ЧТО-ТО НОВОЕ</span><h1>Ваш следующий<br>любимый фильм.</h1><p>Ищите по названию или исследуйте каталог по жанрам, годам и рейтингам.</p></section><form class="searchbar" id="searchForm"><span class="search-icon">⌕</span><input name="keyword" id="searchInput" value="${esc(state.keyword)}" placeholder="Название или ссылка на Кинопоиск…" aria-label="Поиск фильма" autocomplete="off"><button class="search-clear" id="clearSearch" data-action="clearSearch" type="button" aria-label="Очистить поиск" title="Очистить">✕</button><button class="btn primary" type="submit">Найти ↗</button></form><div class="search-message" id="searchMessage" role="status" aria-live="polite"></div><div class="search-filters"><span class="filter-label">Показать:</span><select id="typeFilter" aria-label="Тип"><option value="ALL">Все типы</option><option value="FILM" ${state.type==='FILM'?'selected':''}>Фильмы</option><option value="TV_SERIES" ${state.type==='TV_SERIES'?'selected':''}>Сериалы</option><option value="MINI_SERIES" ${state.type==='MINI_SERIES'?'selected':''}>Мини-сериалы</option><option value="TV_SHOW" ${state.type==='TV_SHOW'?'selected':''}>ТВ-шоу</option></select><select id="genreFilter" aria-label="Жанр"><option value="">Все жанры</option>${filterOptions(state.filters?.genres,'genre')}</select><select id="countryFilter" aria-label="Страна"><option value="">Все страны</option>${filterOptions(state.filters?.countries,'country')}</select><input class="field" type="number" id="yearFilter" placeholder="Год от" min="1890" max="2100" value="${esc(state.year)}" aria-label="Год от"><select id="ratingFilter" aria-label="Минимальный рейтинг"><option value="">Любой рейтинг</option>${[5,6,7,8,9].map(n=>`<option value="${n}" ${state.rating==n?'selected':''}>От ${n} ★</option>`).join('')}</select><select id="sortFilter" aria-label="Сортировка"><option value="RATING" ${state.order==='RATING'?'selected':''}>По рейтингу</option><option value="NUM_VOTE" ${state.order==='NUM_VOTE'?'selected':''}>По популярности оценок</option><option value="YEAR" ${state.order==='YEAR'?'selected':''}>По году</option></select><button class="btn outline small" data-action="clearFilters" type="button">Сбросить</button></div><div class="section-head"><div><span class="eyebrow">РЕЗУЛЬТАТЫ</span><h2 id="catalogCaption">${state.keyword?'Поиск: '+esc(state.keyword):'Открывайте кино'}</h2></div><span class="pill" id="resultCount"></span></div><div id="catalogResult">${apiKey?loading():noKey()}</div><div class="more-wrap" id="more"></div>`}
async function catalog(){root(catalogLayout());if(!apiKey)return;try{if(!state.filters){state.filters=await request('/api/v2.2/films/filters');if(location.hash.startsWith('#catalog')){const genres=$('#genreFilter'),countries=$('#countryFilter');if(genres)genres.innerHTML='<option value="">Все жанры</option>'+filterOptions(state.filters.genres,'genre');if(countries)countries.innerHTML='<option value="">Все страны</option>'+filterOptions(state.filters.countries,'country')}}}catch(e){toast('Фильтры недоступны: '+e.message)}await searchFilms(false)}
async function searchFilms(append){const container=$('#catalogResult');if(!container)return;if(!append)container.innerHTML=loading();
 try{let data;if(state.keyword.trim()&&!state.genre&&!state.country&&!state.year&&!state.rating&&state.type==='ALL')data=await request('/api/v2.1/films/search-by-keyword',{keyword:state.keyword,page:state.page});else data=await request('/api/v2.2/films',{keyword:state.keyword,genres:state.genre,countries:state.country,yearFrom:state.year||undefined,yearTo:undefined,ratingFrom:state.rating||undefined,type:state.type,order:state.order,page:state.page});const items=data.items||data.films||[];if(append){let grid=container.querySelector('.film-grid');if(grid)grid.insertAdjacentHTML('beforeend',items.map(card).join(''));else container.innerHTML=cards(items)}else container.innerHTML=cards(items);const total=data.total??data.searchFilmsCount??null;$('#resultCount').textContent=total===null?'Страница '+state.page:`${total.toLocaleString('ru-RU')} найдено`;const pages=data.totalPages||Math.ceil((total||0)/20);$('#more').innerHTML=(state.page<pages)?'<button class="btn outline" data-action="more">Показать ещё ↓</button>':'';}catch(e){if(!append)container.innerHTML=statusError(e);else toast(e.message);$('#more').innerHTML=''}}
function renderLists(){const arr=lists[state.list];root(`<section class="page-heading"><span class="eyebrow">ТОЛЬКО ВАШЕ</span><h1>Моя коллекция<span class="brand-dot">.</span></h1><p>Сохраняйте планы на вечер, отмечайте просмотренное и собирайте любимые фильмы. Всё хранится в этом браузере.</p></section><div class="list-controls">${Object.entries(listLabels).map(([k,label])=>`<button class="chip ${k===state.list?'active':''}" data-action="listTab" data-list="${k}">${esc(label)} · ${lists[k].length}</button>`).join('')}</div><section class="list-section">${sectionHeading('ЛИЧНАЯ ПОДБОРКА',listLabels[state.list])}${arr.length?cards(arr):`<div class="empty"><div class="em-icon">♡</div><h2>В этом списке пока пусто</h2><p>Откройте интересный фильм и добавьте его в эту коллекцию.</p><a href="#catalog" class="btn primary">Перейти в каталог ↗</a></div>`}</section>`)}
function ageRating(v){const m=String(v||'').match(/(\d{1,2})/);return m?`${Number(m[1])}+`:String(v||'')}
function prettyDate(v,includeTime=false){if(!v)return '';const raw=String(v);const d=new Date(raw);if(Number.isNaN(d.getTime()))return raw;const hasTime=includeTime&&/T\d{2}:\d{2}|\d{2}:\d{2}/.test(raw);const fmt=new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'long',year:'numeric',...(hasTime?{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}:{}) ,timeZone:'UTC'});const parts=fmt.formatToParts(d);const get=t=>parts.find(x=>x.type===t)?.value||'';return `${get('day')} ${get('month')} ${get('year')}г${hasTime?' в '+get('hour')+':'+get('minute'):''}`}
function filmHeader(f){const genres=join(f.genres,'genre');return `<div class="detail-hero"><div class="detail-backdrop" style="${f.coverUrl||f.posterUrl?`background-image:linear-gradient(0deg,var(--surface),transparent 85%),url('${encodeURI(f.coverUrl||f.posterUrl).replace(/'/g,'%27')}')`:''}"></div><div class="detail-body"><div>${img(f.posterUrl,f.nameRu,'detail-poster')}</div><div class="detail-summary"><span class="eyebrow">${esc(f.type==='TV_SERIES'?'СЕРИАЛ':f.type==='MINI_SERIES'?'МИНИ-СЕРИАЛ':'КИНОИСТОРИЯ')}</span><h1>${esc(filmTitle(f))}</h1><div class="detail-tags">${f.year?`<span class="pill">${esc(f.year)}</span>`:''}${f.filmLength?`<span class="pill">${esc(f.filmLength)} мин.</span>`:''}${f.ratingAgeLimits?`<span class="pill">${esc(ageRating(f.ratingAgeLimits))}</span>`:''}${f.ratingKinopoisk?`<span class="pill">★ ${esc(f.ratingKinopoisk)} Кинопоиск</span>`:''}${f.ratingImdb?`<span class="pill">★ ${esc(f.ratingImdb)} IMDb</span>`:''}</div><p>${esc(f.shortDescription||f.description||'Описание не предоставлено.')}</p><div class="detail-action-stack"><div class="detail-actions action-primary"><a class="btn watch-movie" href="${esc('https://kinokino.vip/film/'+idOf(f)+'/')}" target="_blank" rel="noopener noreferrer">▶ Смотреть ${esc(f.type==='TV_SERIES'||f.type==='MINI_SERIES'?'сериал':f.type==='TV_SHOW'?'шоу':'фильм')} ↗</a><a class="btn dark" href="${esc(f.webUrl||'https://www.kinopoisk.ru/film/'+idOf(f)+'/')}" target="_blank" rel="noopener noreferrer">Кинопоиск ↗</a></div><div class="detail-actions action-lists"><button class="btn primary" data-action="detailList" data-list="watchlist">${inList(idOf(f),'watchlist')?'✓ В планах':'♡ Хочу посмотреть'}</button><button class="btn outline" data-action="detailList" data-list="watched">${inList(idOf(f),'watched')?'✓ Просмотрено':'✓ Отметить просмотренным'}</button><button class="btn outline" data-action="detailList" data-list="favorites">${inList(idOf(f),'favorites')?'♥ Любимый':'♡ В любимые'}</button></div></div>${genres?`<div class="muted">${esc(genres)}</div>`:''}</div></div></div>`}

const tabs=[['overview','Обзор'],['cast','Актёры и команда'],['seasons','Сезоны'],['images','Фотогалерея'],['videos','Трейлеры'],['reviews','Рецензии'],['facts','Факты'],['awards','Награды'],['finance','Сборы и прокат'],['related','Похожие и связанные'],['links','Где смотреть']];
function tabHasContent(tab,data){const arr=Array.isArray(data)?data:data?.items||[];if(tab==='seasons')return arr.some(x=>x.episodes?.length);if(tab==='finance')return arr.some(x=>x.amount!==null&&x.amount!==undefined);if(tab==='images')return arr.length>0;if(tab==='videos')return arr.some(x=>x.url);if(tab==='links')return arr.some(x=>x.url);return arr.length>0}
async function prepareTabs(f){const id=idOf(f);const candidates=tabs.filter(([k])=>k!=='overview'&&(k!=='seasons'||['TV_SERIES','MINI_SERIES'].includes(f.type)));const checks=await Promise.allSettled(candidates.map(async([k])=>{const [path,params]=extraPaths[k](f);const data=await request(path,params);return {k,valid:tabHasContent(k,data),data}}));if(state.film!==f)return;const found=new Map();checks.forEach((r,i)=>{if(r.status==='fulfilled'&&r.value.valid)found.set(r.value.k,r.value.data)});state.availableTabs=found;const nav=$('#filmTabs');if(!nav)return;nav.innerHTML=tabs.filter(([k])=>k==='overview'||found.has(k)).map(([k,v])=>`<button class="tab ${state.detailTab===k?'active':''}" role="tab" aria-selected="${state.detailTab===k}" data-action="tab" data-tab="${k}">${v}</button>`).join('');if(state.detailTab!=='overview'&&!found.has(state.detailTab)){state.detailTab='overview';loadTab()}}
function filmLayout(f){state.availableTabs=new Map();root(`<a class="btn outline small back-btn" href="#catalog">← Назад в каталог</a>${filmHeader(f)}<div class="detail-tabs" id="filmTabs" role="tablist"><button class="tab active" role="tab" aria-selected="true" data-action="tab" data-tab="overview">Обзор</button><span class="muted tab-loading">Проверяем доступные разделы…</span></div><section class="detail-content" id="tabContent">${loading()}</section>`)}
async function filmPage(id){state.detailTab='overview';root(loading());try{const f=await request(`/api/v2.2/films/${id}`);if(location.hash!==`#film/${id}`)return;state.film=f;filmLayout(f);await loadTab();prepareTabs(f)}catch(e){root(statusError(e))}}

function dl(f){return Object.entries(f).filter(([,v])=>v!==null&&v!==undefined&&v!==''&&v!==false).map(([k,v])=>`<div class="fact-box"><span>${esc(k)}</span><strong>${esc(String(v))}</strong></div>`).join('')}
function overview(f){const info={'Оригинальное название':f.nameOriginal||f.nameEn,'Год':f.year,'Страна':join(f.countries,'country'),'Жанры':join(f.genres,'genre'),'Продолжительность':f.filmLength?f.filmLength+' мин.':'','Рейтинг Кинопоиска':f.ratingKinopoisk,'Голосов Кинопоиска':f.ratingKinopoiskVoteCount?.toLocaleString('ru-RU'),'Рейтинг IMDb':f.ratingImdb,'Голосов IMDb':f.ratingImdbVoteCount?.toLocaleString('ru-RU'),'Оценка кинокритиков':f.ratingFilmCritics,'Оценка российских критиков':f.ratingRfCritics,'Ожидаемость':f.ratingAwait,'Слоган':f.slogan,'Дата премьеры':prettyDate(f.premiereRu),'Дата релиза в мире':prettyDate(f.premiereWorld),'Дата цифрового релиза':prettyDate(f.premiereDigital),'Возрастное ограничение':ageRating(f.ratingAgeLimits),'MPAA':f.ratingMpaa,'Серий':f.serial?'Сериал':'','Статус':f.completed?'Завершён':'','Страны и производители':f.productionStatus,'Дата синхронизации':prettyDate(f.lastSync,true)};return `<h2>О фильме</h2><p>${esc(f.description||f.shortDescription||'Описание отсутствует.')}</p><h2>Подробная информация</h2><div class="facts-grid">${dl(info)}</div>`}
function itemList(title,items,fn){return `<h2>${title}</h2>${items?.length?items.map(fn).join(''):'<div class="error-note">В API нет сведений для этого раздела.</div>'}`}
const extraPaths={cast:f=>['/api/v1/staff',{filmId:idOf(f)}],seasons:f=>[`/api/v2.2/films/${idOf(f)}/seasons`,{}],images:f=>[`/api/v2.2/films/${idOf(f)}/images`,{type:'STILL',page:1}],videos:f=>[`/api/v2.2/films/${idOf(f)}/videos`,{}],reviews:f=>[`/api/v2.2/films/${idOf(f)}/reviews`,{page:1,order:'DATE_DESC'}],facts:f=>[`/api/v2.2/films/${idOf(f)}/facts`,{}],awards:f=>[`/api/v2.2/films/${idOf(f)}/awards`,{}],finance:f=>[`/api/v2.2/films/${idOf(f)}/box_office`,{}],related:f=>[`/api/v2.2/films/${idOf(f)}/similars`,{}],links:f=>[`/api/v2.2/films/${idOf(f)}/external_sources`,{}]};
async function loadTab(){const f=state.film,tab=state.detailTab,holder=$('#tabContent');if(!f||!holder)return;if(tab==='overview'){holder.innerHTML=overview(f);return}holder.innerHTML=loading();try{const data=state.availableTabs?.get(tab)??await (async()=>{const [path,params]=extraPaths[tab](f);return request(path,params)})();if(state.detailTab!==tab||!$('#tabContent'))return;holder.innerHTML=renderTab(tab,data,f)}catch(e){if($('#tabContent')&&state.detailTab===tab)$('#tabContent').innerHTML=statusError(e)}}
function renderTab(tab,data,f){const items=Array.isArray(data)?data:data.items||[];
 switch(tab){
 case 'cast':{const groups=ROLE_LABELS;const order=ROLE_ORDER;const more=[...new Set(items.map(x=>x.professionKey).filter(x=>!order.includes(x)))];return [...order,...more].map(key=>{const list=items.filter(x=>x.professionKey===key).sort((a,b)=>Number(Boolean(b.posterUrl))-Number(Boolean(a.posterUrl)));return list.length?`<section class="section"><h2>${groups[key]||esc(list[0].profession||key)} <span class="muted tiny">${list.length}</span></h2><div class="people-grid">${list.map(p=>`<a class="person-card" href="#person/${p.staffId}">${p.posterUrl?img(p.posterUrl,p.nameRu):'<div class="poster">▶</div>'}<strong>${esc(p.nameRu||p.nameEn||'Без имени')}</strong><small>${esc(p.description||roleName(p.professionKey))}</small></a>`).join('')}</div></section>`:''}).join('')||'<div class="error-note">Участники не указаны.</div>'}
 case 'seasons':return itemList('Сезоны и эпизоды',items,s=>`<details class="season"><summary>Сезон ${esc(s.number)} · ${s.episodes?.length||0} эпизодов</summary><div class="episodes">${(s.episodes||[]).map(e=>`<div class="episode"><strong>${esc(e.episodeNumber)}. ${esc(e.nameRu||e.nameEn||'Без названия')}</strong><div class="muted tiny">${esc(prettyDate(e.releaseDate)||'Дата неизвестна')}</div>${e.synopsis?`<p>${esc(e.synopsis)}</p>`:''}</div>`).join('')}</div></details>`);
 case 'images':activeGallery=items;return `<div class="split-heading"><h2>Кадры и изображения</h2><select id="imageType" aria-label="Вид изображений">${[['STILL','Кадры'],['SHOOTING','Со съёмок'],['POSTER','Постеры'],['FAN_ART','Фан-арт'],['PROMO','Промо'],['CONCEPT','Концепт-арт'],['WALLPAPER','Обои'],['COVER','Обложки'],['SCREENSHOT','Скриншоты']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div id="imageResults">${gallery(items)}</div>`;
 case 'videos':return itemList('Видео и трейлеры',items,v=>`<div class="video-row"><span><strong>${esc(v.name||'Видео')}</strong><div class="muted tiny">${esc(v.site||'Источник не указан')}</div></span><button class="btn primary small" data-action="playVideo" data-url="${esc(safeUrl(v.url))}" data-title="${esc(v.name||'Трейлер')}">▶ Смотреть здесь</button></div>`);
 case 'reviews':return itemList('Рецензии зрителей',items,r=>{const kind=({POSITIVE:'Положительная',NEGATIVE:'Отрицательная',NEUTRAL:'Нейтральная'}[r.type])||r.type||'Без оценки';const tone=({POSITIVE:'positive',NEGATIVE:'negative',NEUTRAL:'neutral'}[r.type])||'unknown';return `<div class="review review-disclosure" data-review><button class="review-summary" type="button" data-action="toggleReview" aria-expanded="false"><span class="review-heading"><strong>${esc(r.title||'Рецензия')}</strong><small class="muted">${esc(r.author||'Автор не указан')}${r.date?' · '+esc(prettyDate(r.date,true)):''}</small></span><span class="review-status ${tone}">${esc(kind)}</span></button><div class="review-collapse" aria-hidden="true"><div class="review-inner"><div class="review-text">${esc(stripHtml(r.description||''))}</div></div></div></div>`});

 case 'facts':return itemList('Факты и киноляпы',items,x=>`<div class="review"><span class="eyebrow">${x.type==='BLOOPER'?'КИНОЛЯП':'ФАКТ'}</span><p>${esc(stripHtml(x.text||''))}</p>${x.spoiler?'<span class="pill">Может содержать спойлеры</span>':''}</div>`);
 case 'awards':return itemList('Награды и номинации',items,a=>`<div class="review"><h3>${esc(a.name||a.awardName||'Награда')}</h3><p>${esc(a.year||'')} ${a.nominationName?'· '+esc(a.nominationName):''}</p><span class="pill">${a.win?'Победа':'Номинация'}</span>${a.persons?.length?`<p class="muted">${esc(a.persons.map(x=>x.nameRu||x.nameEn).join(', '))}</p>`:''}</div>`);
 case 'finance':return `<h2>Бюджет и сборы</h2><div class="facts-grid">${items.map(x=>`<div class="fact-box"><span>${esc(({BUDGET:'Бюджет',USA:'Сборы в США',WORLD:'Мировые сборы',RUS:'Сборы в России'}[x.type])||x.type||'')}</span><strong>${esc(x.amount?.toLocaleString('ru-RU')||'Нет данных')} ${esc(x.symbol||'')}</strong></div>`).join('')||'<div class="error-note">Сведения отсутствуют.</div>'}</div><div class="section"><button class="btn outline" data-action="distributions">Загрузить данные о прокате ↗</button><div id="distributions"></div></div>`;
 case 'related':return `<h2>Похожие фильмы</h2>${cards(items)}<div class="section"><button class="btn outline" data-action="relations">Загрузить связанные фильмы ↗</button><div id="relations"></div></div>`;
 case 'links':return itemList('Где посмотреть',items,x=>`<div class="video-row"><span><strong>${esc(x.platform||x.name||'Источник')}</strong><div class="tiny muted">${esc(x.type||'')}</div></span><a class="btn outline small" href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">Перейти ↗</a></div>`);
 }
 return '<div class="error-note">Нет информации.</div>';
}
function formatRuDate(s){return prettyDate(s)}
function stripHtml(s){const e=document.createElement('div');e.innerHTML=s;return e.textContent||''}
function safeUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function gallery(items){return items.length?`<div class="gallery-grid">${items.map((x,i)=>`<button type="button" class="gallery-item" data-action="showImage" data-index="${i}" aria-label="Открыть изображение ${i+1}">${img(x.previewUrl||x.imageUrl,'Кадр из фильма')}</button>`).join('')}</div>`:'<div class="error-note">Изображения не найдены.</div>'}
const ROLE_LABELS={ACTOR:'Актёры',DIRECTOR:'Режиссёры',WRITER:'Сценаристы',PRODUCER:'Продюсеры',PRODUCER_USSR:'Продюсеры СССР',OPERATOR:'Операторы-постановщики',COMPOSER:'Композиторы',DESIGN:'Художники',EDITOR:'Монтажёры',VOICE_DIRECTOR:'Режиссёры дубляжа',TRANSLATOR:'Переводчики',HIMSELF:'В роли самого себя',HERSELF:'В роли самой себя',HRONO_TITR_MALE:'Участники хроники',HRONO_TITR_FEMALE:'Участницы хроники',UNKNOWN:'Роль не указана'};
const ROLE_SINGULAR={ACTOR:'Актёр',DIRECTOR:'Режиссёр',WRITER:'Сценарист',PRODUCER:'Продюсер',PRODUCER_USSR:'Продюсер СССР',OPERATOR:'Оператор-постановщик',COMPOSER:'Композитор',DESIGN:'Художник',EDITOR:'Монтажёр',VOICE_DIRECTOR:'Режиссёр дубляжа',TRANSLATOR:'Переводчик',HIMSELF:'В роли самого себя',HERSELF:'В роли самой себя',HRONO_TITR_MALE:'Участник хроники',HRONO_TITR_FEMALE:'Участница хроники',UNKNOWN:'Роль не указана'};
function roleName(key,plural=false){return (plural?ROLE_LABELS:ROLE_SINGULAR)[key] || (key?String(key).replaceAll('_',' ').toLowerCase():'Роль не указана')}
const ROLE_ORDER=['ACTOR','DIRECTOR','WRITER','PRODUCER','PRODUCER_USSR','OPERATOR','COMPOSER','DESIGN','EDITOR','VOICE_DIRECTOR','TRANSLATOR','HIMSELF','HERSELF','HRONO_TITR_MALE','HRONO_TITR_FEMALE','UNKNOWN'];
function roleGroups(items){const groups=new Map();for(const f of items||[]){if(!f.filmId)continue;const k=f.professionKey||'UNKNOWN';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(f)}return [...groups.entries()].sort(([a],[b])=>{const ai=ROLE_ORDER.indexOf(a),bi=ROLE_ORDER.indexOf(b);return (ai<0?999:ai)-(bi<0?999:bi)})}
function filmographyGroup([key,films]){return `<section class="person-role-group"><div class="person-role-heading"><h3>${esc(roleName(key,true))}</h3><span class="pill">${films.length}</span></div><div class="person-film-list">${films.map(f=>`<a class="person-film-row" href="#film/${Number(f.filmId)}"><strong>${esc(f.nameRu||f.nameEn||'Без названия')}</strong><span class="muted">${esc(f.description||'')}</span><span class="person-film-rating">${f.rating&&f.rating!=='null'?'★ '+esc(f.rating):''}</span></a>`).join('')}</div></section>`}
// XLSX generated locally: ZIP (STORE) + OOXML; no CDN, backend or third-party library.
const xmlEsc=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
function makeXlsx(sheets){const encoder=new TextEncoder(),files=[];const excelCol=n=>{let result='';for(n++;n;n=Math.floor((n-1)/26))result=String.fromCharCode(65+(n-1)%26)+result;return result};
const add=(name,str)=>files.push({name,bytes:encoder.encode(str)});
add('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>');
add('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
add('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+sheets.map((s,i)=>`<sheet name="${xmlEsc(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>');
add('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+'</Relationships>');
for(let z=0;z<sheets.length;z++){const sheet=sheets[z],rows=sheet.rows;const cols=Math.max(1,...rows.map(r=>r.length));const widths=Array.from({length:cols},(_,c)=>Math.min(55,Math.max(14,...rows.slice(0,250).map(r=>String(r[c]??'').length))+2));const colTag='<cols>'+widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')+'</cols>';const rxml=rows.map((row,ri)=>`<row r="${ri+1}">`+row.map((v,ci)=>{if(v===null||v===undefined||v==='')return '';let value=String(v);const cell=excelCol(ci)+(ri+1);return typeof v==='number'&&Number.isFinite(v)?`<c r="${cell}"><v>${v}</v></c>`:`<c r="${cell}" t="inlineStr"><is><t xml:space="preserve">${xmlEsc(value.replace(/^[=+@\-]/,'\u0027$&'))}</t></is></c>`}).join('')+'</row>').join('');add(`xl/worksheets/sheet${z+1}.xml`,'<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"/></sheetViews>'+colTag+`<sheetData>${rxml}</sheetData><autoFilter ref="A1:${excelCol(cols-1)}${Math.max(1,rows.length)}"/></worksheet>`)}
const table=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=c&1?0xEDB88320^(c>>>1):c>>>1;table[i]=c>>>0}const crc=buf=>{let c=0xFFFFFFFF;for(const b of buf)c=table[(c^b)&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0};const out=[],central=[];let offset=0;function w16(a,v){a.push(v&255,(v>>>8)&255)}function w32(a,v){w16(a,v&65535);w16(a,v>>>16)}
for(const f of files){const n=encoder.encode(f.name),size=f.bytes.length,check=crc(f.bytes);let h=[];w32(h,0x04034b50);w16(h,20);w16(h,0);w16(h,0);w16(h,0);w16(h,0);w32(h,check);w32(h,size);w32(h,size);w16(h,n.length);w16(h,0);out.push(new Uint8Array(h),n,f.bytes);let c=[];w32(c,0x02014b50);w16(c,20);w16(c,20);w16(c,0);w16(c,0);w16(c,0);w16(c,0);w32(c,check);w32(c,size);w32(c,size);w16(c,n.length);w16(c,0);w16(c,0);w16(c,0);w16(c,0);w32(c,0);w32(c,offset);central.push(new Uint8Array(c),n);offset+=h.length+n.length+size}
let cdlen=central.reduce((v,b)=>v+b.length,0),end=[];w32(end,0x06054b50);w16(end,0);w16(end,0);w16(end,files.length);w16(end,files.length);w32(end,cdlen);w32(end,offset);w16(end,0);return new Blob([...out,...central,new Uint8Array(end)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
let exportingPerson=false;
async function exportPersonExcel(){if(exportingPerson||!state.person)return;exportingPerson=true;const person=state.person;const btn=$('#exportPersonExcel'),progress=$('#exportPersonProgress');if(btn)btn.disabled=true;const all=roleGroups(person.films||[]),unique=[...new Set(all.flatMap(([,arr])=>arr.map(x=>Number(x.filmId))))];const details=new Map();let missing=0;try{for(let i=0;i<unique.length;i++){if(progress)progress.textContent=`Получение сведений: ${i+1} из ${unique.length}`;try{details.set(unique[i],await request(`/api/v2.2/films/${unique[i]}`))}catch(e){missing++;details.set(unique[i],null)}if(i%8===7)await new Promise(r=>setTimeout(r,230))}
const bioRows=[['Поле','Значение'],['Имя',person.nameRu||person.nameEn||''],['Имя на английском',person.nameEn||''],['Профессия',person.profession||''],['Дата рождения',prettyDate(person.birthday)],['Место рождения',person.birthplace||''],['Возраст',person.age??''],['Рост',person.growth??''],['Дата смерти',prettyDate(person.death)],['Место смерти',person.deathplace||''],['Биография',stripHtml(person.biography||'')],['Количество записей фильмографии',(person.films||[]).length],['Источник',`https://www.kinopoisk.ru/name/${person.personId||person.staffId||''}/`],['Примечание',missing?`Для ${missing} фильмов API не вернул подробности; некоторые поля пусты`:'Пустые значения означают отсутствие данных API']];
const head=['Название','Оригинальное название','Год','Тип','Жанры','Рейтинг КП','Рейтинг IMDb','Персонаж / участие','ID Кинопоиска','Ссылка на Кинопоиск'];const sheets=[{name:'Биография',rows:bioRows}];for(const [key,films] of all){const rows=[head,...films.map(f=>{const d=details.get(Number(f.filmId));const numeric=v=>v!==null&&v!==undefined&&v!==''&&!isNaN(Number(v))?Number(v):'';return [d?.nameRu||f.nameRu||f.nameEn||'',d?.nameOriginal||d?.nameEn||f.nameEn||'',d?.year??'',d?.type||'',(d?.genres||[]).map(x=>x.genre).join(', '),numeric(d?.ratingKinopoisk??f.rating),numeric(d?.ratingImdb),f.description||'',Number(f.filmId),`https://www.kinopoisk.ru/film/${Number(f.filmId)}/`]})];const safeName=roleName(key,true).replace(/[\\/*?:\[\]]/g,'').slice(0,31);sheets.push({name:safeName,rows})}if(progress)progress.textContent='Создание Excel…';const blob=makeXlsx(sheets),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`Кинотека_${(person.nameRu||person.nameEn||'Персона').replace(/[\\/:*?"<>|]/g,'_')}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);if(progress)progress.textContent=`Готово. ${unique.length} фильмов, без подробностей: ${missing}`;toast('Excel-файл фильмографии готов')}catch(e){if(progress)progress.textContent='Ошибка: '+e.message;toast('Ошибка экспорта: '+e.message)}finally{exportingPerson=false;if(btn)btn.disabled=false}}
async function personPage(id){root(loading());try{const p=await request('/api/v1/staff/'+id);if(location.hash!==`#person/${id}`)return;state.person=p;const groups=roleGroups(p.films||[]);root(`<a class="btn outline small back-btn" href="javascript:history.back()">← Назад</a><section class="detail-hero" style="padding:28px"><div class="detail-body" style="margin:0;padding:0"><div>${img(p.posterUrl,p.nameRu,'detail-poster')}</div><div class="detail-summary" style="padding-top:5px"><span class="eyebrow">КИНОПЕРСОНА</span><h1>${esc(p.nameRu||p.nameEn||'Без имени')}</h1><div class="facts-grid">${dl({'Имя на английском':p.nameEn,'Профессия':p.profession,'Дата рождения':prettyDate(p.birthday),'Место рождения':p.birthplace,'Рост':p.growth?p.growth+' см':'','Возраст':p.age,'Дата смерти':prettyDate(p.death),'Место смерти':p.deathplace,'Количество работ':p.films?.length})}</div>${p.biography?`<details class="person-biography"><summary>Биография</summary><p>${esc(stripHtml(p.biography))}</p></details>`:''}</div></div></section><section class="section">${sectionHeading('ФИЛЬМОГРАФИЯ','Фильмы и сериалы')}<div class="person-export"><button class="btn primary" type="button" id="exportPersonExcel" data-action="exportPersonExcel">↓ Экспортировать в Excel</button><span class="muted tiny" id="exportPersonProgress">Каждая роль — отдельный лист, жанры и рейтинги загружаются из API</span></div>${groups.length?groups.map(filmographyGroup).join(''):'<p class="muted">Нет фильмографии в API.</p>'}</section>`)}catch(e){root(statusError(e))}}
function route(){const h=decodeURIComponent(location.hash.replace(/^#/,''));const [name,arg]=h.split('/');scrollTo({top:0,behavior:'instant'});if(name==='collection'&&['TOP_POPULAR_MOVIES','TOP_250_MOVIES'].includes(arg))return collectionPage(arg);if(name==='catalog')return catalog();if(name==='lists')return renderLists();if(name==='film'&&/^\d+$/.test(arg))return filmPage(Number(arg));if(name==='person'&&/^\d+$/.test(arg))return personPage(Number(arg));return home()}
function settings(){const d=$('#settingsDialog');$('#apiKey').value=apiKey;$('#rememberKey').checked=!!localStorage.getItem(keyName);$('#keyStatus').textContent=apiKey?'Ключ введён':'Ключ ещё не подключён';d.showModal()}
function persistKey(){const key=$('#apiKey').value.trim();if(!key){$('#keyStatus').textContent='Введите API-ключ';return}apiKey=key;cache.clear();if($('#rememberKey').checked){localStorage.setItem(keyName,key);sessionStorage.removeItem(keyName)}else{sessionStorage.setItem(keyName,key);localStorage.removeItem(keyName)}$('#keyStatus').textContent='Проверка соединения…';request('/api/v2.2/films/301',{},{noCache:true}).then(()=>{$('#keyStatus').textContent='✓ Соединение успешно';$('#settingsDialog').close();toast('API подключён');route()}).catch(e=>{$('#keyStatus').textContent='Ошибка: '+e.message;toast(e.message)})}
function clearKey(){apiKey='';localStorage.removeItem(keyName);sessionStorage.removeItem(keyName);cache.clear();$('#apiKey').value='';$('#keyStatus').textContent='Ключ удалён';toast('Ключ удалён');route()}
function refreshCardHearts(){document.querySelectorAll('[data-action="watch"]').forEach(btn=>{const yes=inList(btn.dataset.id,'watchlist');btn.classList.toggle('on',yes);btn.textContent=yes?'♥':'♡';btn.setAttribute('aria-label',yes?'Убрать из списка':'Хочу посмотреть')})}
function findFilm(id){return state.film&&idOf(state.film)===id?state.film:knownFilms.get(id)||lists.watchlist.concat(lists.watched,lists.favorites).find(x=>idOf(x)===id)||{kinopoiskId:id,nameRu:'Фильм '+id}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='exportPersonExcel')exportPersonExcel();
 if(a==='settings')settings();
 if(a==='collectionPage')collectionPage(b.dataset.type,Number(b.dataset.page));
 if(a==='genreJump'){state.genre=b.dataset.genre;state.keyword='';state.page=1;location.hash='#catalog';if(location.hash==='#catalog'&&$('#catalogResult'))catalog()}
 if(a==='clearSearch'){clearTimeout(invalidLinkTimer);state.keyword='';const input=$('#searchInput');if(input){input.value='';input.focus()}const msg=$('#searchMessage');if(msg)msg.textContent='';state.page=1;searchFilms(false)}
 if(a==='showImage'){currentImage=Number(b.dataset.index);showGalleryImage()}
 if(a==='imagePrev'){currentImage=(currentImage-1+activeGallery.length)%activeGallery.length;showGalleryImage()}
 if(a==='imageNext'){currentImage=(currentImage+1)%activeGallery.length;showGalleryImage()}
 if(a==='playVideo')openVideo(b.dataset.url,b.dataset.title);
 if(a==='hdTitleSearch'){const q=$('#hdTitle')?.value.trim();if(q){state.keyword=q;state.page=1;const i=$('#searchInput');if(i)i.value='';const m=$('#searchMessage');if(m)m.textContent='Ищем: '+q;searchFilms(false)}}
 if(a==='watch'){e.preventDefault();toggleList(findFilm(Number(b.dataset.id)),'watchlist');refreshCardHearts();if(location.hash==='#lists')renderLists()}
 if(a==='detailList'&&state.film){toggleList(state.film,b.dataset.list);filmLayout(state.film);loadTab()}
 if(a==='listTab'){state.list=b.dataset.list;renderLists()}
 if(a==='toggleReview'){const box=b.closest('[data-review]');const open=box.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open));box.querySelector('.review-collapse')?.setAttribute('aria-hidden',String(!open));}
 if(a==='tab'){state.detailTab=b.dataset.tab;document.querySelectorAll('.tab').forEach(x=>{x.classList.toggle('active',x.dataset.tab===state.detailTab);x.setAttribute('aria-selected',String(x.dataset.tab===state.detailTab))});loadTab()}
 if(a==='more'){state.page++;await searchFilms(true)}
 if(a==='clearFilters'){Object.assign(state,{keyword:'',type:'ALL',genre:'',country:'',year:'',rating:'',order:'RATING',page:1});catalog()}
 if(a==='retry')route();
 if(a==='distributions'&&state.film){const holder=$('#distributions');holder.innerHTML=loading();try{const d=await request(`/api/v2.2/films/${idOf(state.film)}/distributions`);holder.innerHTML=itemList('Прокат',d.items||[],x=>`<div class="review"><strong>${esc(x.type||'Прокат')}</strong><p>${esc(x.date||'')} · ${esc(x.country?.country||'')} ${x.companies?.length?' · '+esc(x.companies.map(z=>z.name).join(', ')):''}</p></div>`)}catch(err){holder.innerHTML=statusError(err)}}
 if(a==='relations'&&state.film){const holder=$('#relations');holder.innerHTML=loading();try{const d=await request(`/api/v2.2/films/${idOf(state.film)}/relations`);holder.innerHTML=cards(d.items||[])}catch(err){holder.innerHTML=statusError(err)}}
});
async function processSearch(raw){
 const input=$('#searchInput'),msg=$('#searchMessage');clearTimeout(invalidLinkTimer);const q=raw.trim();
 const isUrl=/^https?:\/\//i.test(q)||/^(?:www\.)?(?:hd\.)?kinopoisk\.ru\//i.test(q);
 if(!isUrl){state.keyword=q;state.page=1;await searchFilms(false);return}
 let u;try{u=new URL(/^https?:\/\//i.test(q)?q:'https://'+q)}catch{u=null}
 const hostname=u?.hostname.toLowerCase();const kp=hostname==='kinopoisk.ru'||hostname==='www.kinopoisk.ru';
 const direct=kp&&u.pathname.match(/^\/(?:film|series|tv)\/(\d+)(?:\/|$)/i);
 if(direct){if(input)input.value='';if(msg)msg.textContent='Открываем карточку…';location.hash='#film/'+direct[1];return}
 if(hostname==='hd.kinopoisk.ru'&&/^\/(?:[a-z]{2}(?:-[a-z]{2})?\/)?film\//.test(u.pathname)){
   if(input)input.value='';if(msg)msg.innerHTML='Определяем название по ссылке Кинопоиска…';
   const token=++hdRequestToken;
   try{const response=await fetch(u.href,{signal:AbortSignal.timeout(7000)});if(!response.ok)throw Error('Страница недоступна');const html=await response.text();
     const doc=new DOMParser().parseFromString(html,'text/html');let title=doc.querySelector('meta[property="og:title"]')?.content||doc.title||'';
     title=title.replace(/\s*[|—–-]\s*(?:Кинопоиск|смотреть онлайн).*$/i,'').trim();
     if(!title||title.toLowerCase()==='кинопоиск')throw Error('Название не найдено');
     if(token!==hdRequestToken)return;state.keyword=title;if(msg)msg.textContent='Найдено название: '+title;state.page=1;await searchFilms(false);
   }catch(e){if(token!==hdRequestToken)return;showHdFallback(u.href)}return;
 }
 if(msg)msg.textContent='Эта ссылка не поддерживается. Поле будет очищено через 5 секунд.';
 invalidLinkTimer=setTimeout(()=>{if(input&&input.value.trim()===q)input.value='';if(msg)msg.textContent=''},5000);
}
function showHdFallback(url){const msg=$('#searchMessage');if(!msg)return;msg.innerHTML=`<div class="hd-fallback"><strong>Не удалось прочитать название из ссылки HD Кинопоиска</strong><p>HD-ссылки используют другой ID. Браузер может блокировать чтение страницы (CORS). Введите название фильма — выполним поиск по нему.</p><div class="fallback-input"><input id="hdTitle" placeholder="Введите название фильма или сериала" aria-label="Название фильма"><button class="btn primary small" data-action="hdTitleSearch">Найти</button></div><a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="inline-link">Открыть исходную страницу ↗</a></div>`}
document.addEventListener('submit',e=>{if(e.target.id!=='searchForm')return;e.preventDefault();processSearch($('#searchInput').value)});
document.addEventListener('input',e=>{if(e.target.id!=='searchInput')return;clearTimeout(invalidLinkTimer);const q=e.target.value.trim();if(/^https?:\/\/|^(?:www\.)?(?:hd\.)?kinopoisk\.ru\//i.test(q))processSearch(q)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=$('#mediaDialog');if(d?.open)d.close()}if($('#mediaDialog')?.open&&e.key==='ArrowLeft'&&activeGallery.length>1){currentImage=(currentImage-1+activeGallery.length)%activeGallery.length;showGalleryImage()}if($('#mediaDialog')?.open&&e.key==='ArrowRight'&&activeGallery.length>1){currentImage=(currentImage+1)%activeGallery.length;showGalleryImage()}});
document.addEventListener('change',async e=>{const ids={typeFilter:'type',genreFilter:'genre',countryFilter:'country',yearFilter:'year',ratingFilter:'rating',sortFilter:'order'};if(ids[e.target.id]){state[ids[e.target.id]]=e.target.value;state.page=1;await searchFilms(false)}if(e.target.id==='imageType'&&state.film){const holder=$('#imageResults');holder.innerHTML=loading();try{const data=await request(`/api/v2.2/films/${idOf(state.film)}/images`,{type:e.target.value,page:1});activeGallery=data.items||[];holder.innerHTML=gallery(activeGallery)}catch(err){holder.innerHTML=statusError(err)}}});

function showGalleryImage(){
 const x=activeGallery[currentImage];if(!x)return;const d=$('#mediaDialog'),container=$('#mediaContent');
 container.innerHTML=`<div class="viewer"><img src="${esc(safeUrl(x.imageUrl||x.previewUrl))}" alt="Изображение ${currentImage+1}" referrerpolicy="no-referrer"><div class="viewer-toolbar"><button class="btn outline small" data-action="imagePrev" ${activeGallery.length<2?'disabled':''}>← Назад</button><span>${currentImage+1} / ${activeGallery.length}</span><button class="btn outline small" data-action="imageNext" ${activeGallery.length<2?'disabled':''}>Далее →</button></div></div>`;
 if(!d.open)d.showModal();
}
function videoEmbed(raw){
 try{const u=new URL(raw),host=u.hostname.replace(/^www\./,'').toLowerCase();let id='';
 if(host==='youtu.be')id=u.pathname.split('/')[1]||'';
 if(['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(host))id=u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts|live)\/([^/]+)/)?.[1]||'';
 if(id&&/^[\w-]{11}$/.test(id))return {kind:'iframe',url:'https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1'};
 if(host==='rutube.ru'){id=u.pathname.match(/^\/video\/([a-z0-9]+)/i)?.[1]||u.pathname.match(/^\/play\/embed\/([a-z0-9]+)/i)?.[1]||'';if(id)return {kind:'iframe',url:'https://rutube.ru/play/embed/'+id}};
 if(host==='player.vimeo.com'||host==='vimeo.com'){id=u.pathname.match(/(\d+)/)?.[1]||'';if(id)return {kind:'iframe',url:'https://player.vimeo.com/video/'+id+'?autoplay=1'}}
 if(host==='vk.com'||host==='vkvideo.ru'){const oid=u.searchParams.get('oid'),vid=u.searchParams.get('id');if(oid&&vid&&/^-?\d+$/.test(oid)&&/^\d+$/.test(vid))return {kind:'iframe',url:'https://vk.com/video_ext.php?oid='+oid+'&id='+vid+'&autoplay=1'}}
 if(/\.(mp4|webm|ogg)(?:$|\?)/i.test(u.pathname+u.search))return {kind:'video',url:u.href};
 }catch{}return null;
}
function openVideo(raw,title){const d=$('#mediaDialog'),container=$('#mediaContent'),embed=videoEmbed(raw);
 if(embed){container.innerHTML=`<div class="player"><h2>${esc(title||'Трейлер')}</h2>${embed.kind==='video'?`<video src="${esc(embed.url)}" controls autoplay playsinline></video>`:`<iframe src="${esc(embed.url)}" title="${esc(title||'Видеоплеер')}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`}<p class="muted tiny">Воспроизведение зависит от разрешений видеохостинга. Некоторые ролики могут запрещать встраивание.</p></div>`}
 else container.innerHTML=`<div class="player"><h2>${esc(title||'Трейлер')}</h2><p>Этот источник не предоставил поддерживаемую ссылку для встроенного проигрывателя.</p><a class="btn outline" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(raw))}">Открыть на видеохостинге ↗</a></div>`;
 if(!d.open)d.showModal();
}
$('#mediaDialog').addEventListener('close',()=>{$('#mediaContent').replaceChildren()});
$('#mediaDialog').addEventListener('click',e=>{if(e.target.id==='mediaDialog')e.target.close()});

$('#settingsBtn').addEventListener('click',settings);$('#mobileSettings').addEventListener('click',settings);
$('#saveKey').addEventListener('click',persistKey);$('#clearKey').addEventListener('click',clearKey);
$('#showKey').addEventListener('click',()=>{const i=$('#apiKey');i.type=i.type==='password'?'text':'password';$('#showKey').textContent=i.type==='password'?'Показать':'Скрыть'});
$('#themeToggle').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('kinoteka.theme',next);$('#themeToggle').textContent=next==='dark'?'☀':'☾'});
const initTheme=localStorage.getItem('kinoteka.theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');document.documentElement.dataset.theme=initTheme;$('#themeToggle').textContent=initTheme==='dark'?'☀':'☾';
$('#exportLists').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),lists},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='kinoteka-lists.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
$('#importLists').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const json=JSON.parse(await file.text());if(!json.lists||!Object.values(defaultLists).every((_,i)=>Array.isArray(json.lists[Object.keys(defaultLists)[i]])))throw Error('Неверный формат файла');if(!confirm('Заменить все локальные списки содержимым этого файла?'))return;lists=Object.fromEntries(Object.keys(defaultLists).map(k=>[k,json.lists[k].filter(x=>Number.isSafeInteger(idOf(x))&&idOf(x)>0).map(compactFilm)]));writeLists();toast('Списки импортированы');$('#settingsDialog').close();route()}catch(err){toast('Ошибка импорта: '+err.message)}e.target.value=''});
window.addEventListener('hashchange',route);route();
